cat >> packs/claudinite-lifecycle/test/update-worker.test.mjs <<'EOF'

// #1545's second half. Holding an owing pack's stamp means a re-staging cycle can leave
// the tree CLEAN — the staged bytes already on the branch, no version line to rewrite —
// and the worker's "nothing changed" guard returns before the PR is opened. The
// apply-stage request is written after that PR, so the guard firing on an apply-stage
// terminal means nobody is ever asked to deliver the file: the same silent loss, one
// step further along. Only `merge` and `keep` may take the early exit.
test('the "nothing changed" guard never swallows an apply-stage terminal', async () => {
  const fs = await import('node:fs');
  const src = fs.readFileSync('packs/claudinite-lifecycle/tasks/update/worker.mjs', 'utf8');
  const guard = src.slice(src.indexOf("const changed = git("));
  const body = guard.slice(0, guard.indexOf('}') + 1);
  assert.match(body, /terminal\.action !== 'apply-stage'/,
    'an apply-stage terminal owes a delivery, so it must reach the PR that requests it');
  // And the request really does sit after the PR, which is what makes the guard fatal.
  assert.ok(src.indexOf("'agent-requested'") > src.indexOf('/repos/${repo}/pulls'),
    'if the request ever moves above PR creation, this guard stops being load-bearing');
});
EOF
node --test packs/claudinite-lifecycle/test/update-worker.test.mjs 2>&1 | grep -E "not ok|^# (pass|fail)|nothing changed"

cat >> engine-tests/pack-update.test.mjs <<'EOF'

// TWO PACKS, ONE WORKFLOW PATH (#1545). `withheld` is de-duplicated by path, so a second
// record naming a path the first already staged grows it by nothing — while its content
// is what actually sits in the staging directory. Attributing the hold by counting
// `withheld` would therefore stamp the pack whose delivery is the one still owed, which
// is the original bug with an extra step. The attribution is made as each write happens.
test('two packs staging the same workflow path are BOTH held back', async () => {
  const root = makeMember({ packs: ['basics', 'claudinite-tasks', 'claudinite-lifecycle'] });
  assert.deepEqual((await applyVendor(root)).errors, []);
  setStamp(root, { packVersions: { 'claudinite-tasks': '60831.5', 'claudinite-lifecycle': '60831.1' } });
  mkdirSync(join(root, '.github', 'workflows'), { recursive: true });
  writeFileSync(join(root, EXECUTOR_WORKFLOW), 'name: Claudinite executor\n# MARKER\n');

  const record = (pack, from, to) => ({
    id: `test-${pack}`,
    dir: `packs/${pack}/migrations/test-shared-workflow`,
    rewrite: [{ file: EXECUTOR_WORKFLOW, replace: [{ from, to }] }],
    applyStage: { why: 'a workflow file was withheld and needs delivering' },
  });
  const r = await packUpdate(root, {
    fullName: 'o/r',
    selfTestRun: () => 'ok',
    extraRecords: [
      record('claudinite-tasks', '# MARKER', '# FIRST'),
      record('claudinite-lifecycle', '# FIRST', '# SECOND'),
    ],
  });

  // One path, so `withheld` holds a single entry — the exact shape a count misreads.
  assert.deepEqual(r.withheld, [EXECUTOR_WORKFLOW]);
  const stamped = stampOf(root).packVersions;
  assert.equal(stamped['claudinite-tasks'], '60831.5', 'the first record owes its delivery');
  assert.equal(stamped['claudinite-lifecycle'], '60831.1',
    'and so does the second, whose content is the one actually staged');
  removeTree(root);
});
EOF
node --test engine-tests/pack-update.test.mjs 2>&1 | grep -E "not ok|^# (pass|fail)|BOTH held"

